public static boolean isPalindrome(String s, int low, int high) {
  if (low >= high) return true;
                                                        // Base case
  if (s.charAt(low) != s.charAt(high)) return false; // Base case
  return isPalindrome(s, low+1, high-1);
                                                  // Recursive call
}

